INSERT OR IGNORE INTO dishes VALUES('9135b8c4-cc20-4e54-91d6-a9afc0586a4b','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Say Cheese Pizza','Artisan Pizzas',9.49000000000000021,'A timeless classic, perfected. Our rich, vibrant tomato sauce and a generous blanket of perfectly melted, creamy mozzarella on our signature artisan crust.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('950b6b78-20b9-45d4-b50a-b359af675b8f','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Bianca Pizza','Artisan Pizzas',12.94999999999999929,'An elegant white pizza featuring a garlic-infused base, topped with creamy mozzarella and tangy feta, savory sausage, and fresh florets of broccoli.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('3adc765e-acea-45a5-ae26-566ae1489d62','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','The Queen Pizza','Artisan Pizzas',12.94999999999999929,'A royal tribute to Italian tradition. Our classic tomato base is adorned with fresh, creamy mozzarella, fragrant basil, a whisper of garlic, and a kiss of fresh oregano and Parmesan.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('f5036327-98d7-4d43-82c8-ff86e47d1c6b','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Homecoming Pizza','Artisan Pizzas',10.94999999999999928,'The familiar taste of home, elevated. A comforting classic with our signature tomato sauce, melted mozzarella, and savory, crisp-edged pepperoni.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('d1a0a326-4422-46ed-a984-17c8f8dc10b3','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','The Brown''s Pizza','Artisan Pizzas',12.94999999999999929,'A Mediterranean dream. A vibrant pesto base layered with mozzarella, sun-ripened tomatoes, feta cheese, garlic, tender spinach, and rich Kalamata olives.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('9107ebd9-bc4a-4f18-b139-a1a631b40d5e','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Henry''s Pizza','Artisan Pizzas',12.94999999999999929,'A daring and delicious dance of sweet and heat. This pizza features fresh mozzarella and aromatic basil, all brought to life with a drizzle of sweet balsamic glaze and a surprising kick of hot honey.','[{"tag":"dairy","source":"stated"},{"tag":"spicy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('b0288d89-7663-416b-8a54-ee6705c8caa2','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Buffalo''s Pizza','Artisan Pizzas',12.94999999999999929,'All the flavor of your favorite wings on a pizza! A zesty buffalo & ranch base topped with mozzarella, tender chicken, and savory bacon.','[{"tag":"dairy","source":"stated"},{"tag":"poultry","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"spicy","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('aca6bc33-c607-4f11-b0a0-c694894ee1a0','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','GiarDino Pizza','Artisan Pizzas',12.94999999999999929,'A fresh and vibrant trip through the garden. Our tomato base is topped with mozzarella, spinach, tomatoes, onions, bell peppers, artichoke hearts, and mushrooms.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('4d1af8fe-820f-47e9-9f8a-fc7d037498ca','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','La Toscana Pizza','Artisan Pizzas',12.94999999999999929,'A taste of the Tuscan countryside. Fragrant pesto provides the base for mozzarella, spinach, sweet grilled onions, feta, garlic, and a finishing drizzle of rich balsamic glaze.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('544395f9-7494-4958-adc8-dde03351463f','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','La Fiesta Pizza','Artisan Pizzas',12.94999999999999929,'A celebration of bold flavors! A smoky BBQ sauce base with melted cheddar and mozzarella cheeses, topped with tender, seasoned chicken.','[{"tag":"dairy","source":"stated"},{"tag":"poultry","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('dc23f50b-9f65-4e1b-8ab9-9787df883fce','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Philly''s Pizza','Artisan Pizzas',12.94999999999999929,'A taste of the City of Brotherly Love. A creamy ranch base topped with mozzarella, tender steak, and a medley of sweet bell peppers and onions.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"beef","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('6f1a36c4-2a1c-4b71-a2d8-587caf218d58','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Supremo Pizza','Artisan Pizzas',12.94999999999999929,'The ultimate pizza experience. A flavor explosion of pepperoni, bacon, sausage, bell peppers, onions, and green olives over our classic tomato sauce and mozzarella.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('a04fccb9-d0dc-461b-a957-eb16f0f4aafb','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Aloha Pizza','Artisan Pizzas',12.94999999999999929,'A sweet and savory escape to the islands. Our signature tomato sauce and mozzarella, topped with savory ham and sweet, juicy pineapple.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('20a65fb5-2570-4e87-9f7b-26f7b71a0832','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Dino''s Pizza','Artisan Pizzas',12.94999999999999929,'Named for the man himself, this is a celebration of Italian flavor. A creamy ricotta base with mozzarella, savory sausage, garlic, spinach, onions, and a final, shimmering drizzle of extra virgin olive oil.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('a0fb8c25-b0d6-403d-9533-71caefdf48c4','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Meatlovers Pizza','Artisan Pizzas',12.94999999999999929,'A hearty feast for the senses. A savory masterpiece loaded with pepperoni, bacon, sausage, and ham over our classic tomato sauce and melted mozzarella.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('81753000-70f9-4675-bd07-2dd850b31925','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Build Your Own Pizza','Artisan Pizzas',9.90000000000000035,NULL,'[{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('171dc4ff-a223-4548-812b-c6697658fec6','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Build Your Own Bowl','Bowls',12.94999999999999929,'Build your own bowl with 1 base, 4 fresh vegetables, 1 protein of your choice, and finish it with 2 garnishes.','[]');
INSERT OR IGNORE INTO dishes VALUES('e2875f84-4c25-43de-ab30-b6054ded2968','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','TexMex Bowl','Bowls',12.94999999999999929,'A hearty bowl with fluffy rice and tender chicken, topped with fresh pico de gallo, sweet corn, creamy guacamole, melted cheese, and cool sour cream, finished with crunchy chips and a drizzle of smoky chipotle sauce.','[{"tag":"poultry","source":"stated"},{"tag":"dairy","source":"stated"}]');
INSERT OR IGNORE INTO dishes VALUES('4971858a-9846-4fbb-a803-6ba3fcca9fbf','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Mediterranean Bowl','Bowls',12.94999999999999929,'A fresh and vibrant bowl with fluffy rice and tender chicken, layered with crisp lettuce, creamy coleslaw, juicy tomatoes, and crunchy cucumbers, topped with tangy feta cheese and a cool drizzle of tzatziki sauce.','[{"tag":"poultry","source":"stated"},{"tag":"dairy","source":"stated"}]');
INSERT OR IGNORE INTO dishes VALUES('7637edd2-4af4-45b7-ae7e-afa24f4df928','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Falafel Bowl','Bowls',11.94999999999999929,'A flavorful bowl with fluffy rice and crispy falafel, paired with fresh greens, juicy tomatoes, crunchy cucumbers, and onions, topped with creamy hummus and a cool drizzle of tzatziki sauce.','[{"tag":"dairy","source":"inferred"},{"tag":"sesame","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('9d39e495-b103-4db0-a375-99ebf966175d','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Build your own Calzone','Calzones',8.0,'Build your own calzone: start with our house-made dough, choose your favorite fillings from fresh vegetables, savory meats, and cheeses, then we fold and bake it golden brown, served hot and melty from the oven.','[{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('dc7cf54e-0e43-4523-b515-bba5476a885c','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Chicken Bacon Ranch Calzone','Calzones',13.0,'Chicken Bacon Ranch Calzone is packed with tender chicken, crispy bacon, and melted cheese, folded in our house-made dough and baked golden brown, finished with a drizzle of creamy ranch.','[{"tag":"poultry","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('582c38f2-ebe9-4f7c-b93d-ede131257f01','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Buffalo Chicken Calzone','Calzones',13.0,'A bold calzone stuffed with tender chicken, melted cheese, and our spicy Buffalo sauce, folded in house-made dough, baked golden, and served with a side of cool ranch.','[{"tag":"poultry","source":"stated"},{"tag":"dairy","source":"stated"},{"tag":"spicy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('32097e35-4a92-4b21-9227-719e473e8172','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Veggie Calzone','Calzones',13.0,'A hearty calzone filled with fresh vegetables, melted cheese, and our signature house-made dough, baked to golden perfection and served hot from the oven.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('e7b0da2c-b2ea-40ab-bf94-08831651591e','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Pepperoni Calzone','Calzones',10.0,'A classic calzone loaded with zesty pepperoni and melted cheese, wrapped in our house-made dough and baked golden brown to perfection.','[{"tag":"meat","source":"stated"},{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
