INSERT OR IGNORE INTO dishes VALUES('b403a5d3-b31e-4ca9-8497-7554c45829f2','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Falafel Wrap','Wraps',9.0,'Our famous house-made falafel, lightly crisped and nestled in a bed of fresh mixed greens with tomato and cucumber, finished with a creamy, flavorful combination of our homemade hummus and tzatziki.','[{"tag":"gluten","source":"inferred"},{"tag":"sesame","source":"inferred"},{"tag":"dairy","source":"inferred"}]');
