INSERT OR IGNORE INTO dishes VALUES('44a17de1-8b2c-4eb4-827d-a2f7913f6fed','b9cf1ea9-7203-40d2-8e12-909928c21a93','d256119f-e831-4a42-a3bc-1812e2ebd745','Deli banh mi','HEARTY SOUP and SANDWICH',11.5,'Vietnamese plant based deli protein, mushroom pate, vegan mayo, cucumber, pickled daikon and carrots, cilantro and soy sauce.','[{"tag":"gluten","source":"inferred"},{"tag":"soy","source":"stated"}]');
INSERT OR IGNORE INTO dishes VALUES('4579c5f8-13c0-4da7-a5d2-d1843935963a','b9cf1ea9-7203-40d2-8e12-909928c21a93','d256119f-e831-4a42-a3bc-1812e2ebd745','Pho''','HEARTY SOUP and SANDWICH',16.94999999999999929,'Fried garlic or steamed tofu, garlic shitake mushrooms, snow peas, and fresh rice noodles in a full-flavored vegetable broth. Includes bean sprouts, Thai basil, and a wedge of lime.','[{"tag":"soy","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('e8e9e48a-955e-4aba-b1da-af0688507ce2','b9cf1ea9-7203-40d2-8e12-909928c21a93','d256119f-e831-4a42-a3bc-1812e2ebd745','Ginger Lemongrass Noodle Soup','HEARTY SOUP and SANDWICH',15.94999999999999929,'Fresh ginger and lemongrass infused tofu in a house vegetarian broth rice noodles with baby greens, bean sprouts, caramelized onions, Thai basil, cilantro and lime. **Let us know if you are eating at home, we''ll separate the noodles from the broth for a better eating experience.','[{"tag":"soy","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('3ab6633f-c368-4a65-986f-49323f6d07f5','b9cf1ea9-7203-40d2-8e12-909928c21a93','d256119f-e831-4a42-a3bc-1812e2ebd745','Bun bo hue chay (Vegan spicy Vietnamese beef soup)','HEARTY SOUP and SANDWICH',16.94999999999999929,'Vegan Vietnamese spicy beef soup, plant based beef, tofu, vegan cha lua ( vegan Vietnamese ham), thick rice noodles, bean sprouts in our flavorful veg. broth, herbs, and lime. Ask for chili oil for more spicy.','[{"tag":"spicy","source":"stated"},{"tag":"soy","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('0ce2fbe6-668f-44c1-9266-d7884a8f29b5','b9cf1ea9-7203-40d2-8e12-909928c21a93','d256119f-e831-4a42-a3bc-1812e2ebd745','Ginger Lemongrass Tofu Noodles','DRY NOODLES',13.94999999999999929,'Fresh ginger and lemongrass infused tofu and onions over rice noodles with baby greens fresh shredded carrots and Thai basil. Serves with ginger soy sauce. *When choose a GF ginger soy, this bowl can be GF.','[{"tag":"soy","source":"stated"}]');
INSERT OR IGNORE INTO dishes VALUES('7a2e94e5-e3e7-46f6-8420-0dc02b6f74dd','b9cf1ea9-7203-40d2-8e12-909928c21a93','d256119f-e831-4a42-a3bc-1812e2ebd745','Make Your Own Bowl','DRY NOODLES',14.94999999999999929,'Make your own bowl Protein: Fried tofu, five-spice tofu and ginger lemongrass tofu Noodles: Rice noodles(GF) and wide noodles Vegetables: Baby greens, bean sprouts, shred carrots, caramelized onions, Thai basil, cilantro and/or peanuts. Sauces: Fish sauce or ginger soy','[{"tag":"soy","source":"inferred"}]');
