INSERT OR IGNORE INTO reviews VALUES('cfcce348-98e7-4d30-8774-bebc7133e4fb','6d1d6697-8aaa-4257-b26c-25f8b9173150','google:Ci9DQUlRQUNvZENodHljRjlvT2pkUVdHd3pka3RSWm05bWNFVndUVmcxZEZoMGMwRRAB','google','The pollo loco was delicious! Buttery grilled chicken with a sauce that''s on the spicy side.',5,'2026-06-17','2026-11-12T02:03:12.175Z');
