INSERT OR IGNORE INTO reviews VALUES('7a26e864-f237-410f-8a92-fe829e15cb90','6d1d6697-8aaa-4257-b26c-25f8b9173150','google:ChZDSUhNMG9nS0VMMzB4TEttcWU2bWFnEAE','google','This place deserves 5 stars for quality service and price. Love this places it''s my go to. Loveeeee the ranchero sauce yum',5,'2025-05-30','2026-11-12T02:03:12.175Z');
