INSERT OR IGNORE INTO reviews VALUES('14fe41b9-458d-4049-9d64-91553633aea0','6d1d6697-8aaa-4257-b26c-25f8b9173150','google:ChZDSUhNMG9nS0VKM1Q4ZWFSMF9QZFhREAE','google','Live up the hill, order from el Puerto all the time and the quality and value are both very good + and a fantastic combination.',5,'2025-05-24','2026-11-12T02:03:12.175Z');
INSERT OR IGNORE INTO reviews VALUES('58eadf0c-56b8-4c5a-bb2d-9470d84a6b32','6d1d6697-8aaa-4257-b26c-25f8b9173150','google:ChdDSUhNMG9nS0VOVFE1WXFBOVAtbTRRRRAB','google','I asked my daughter (who just graduated from UVA) for a referral on a Mexican restaurant. Let’s just say that if we lived closer, we’d be eating here EVERY week. Great food!',5,'2025-05-18','2026-11-12T02:03:12.175Z');
