INSERT OR IGNORE INTO reviews VALUES('1cc63698-ec6c-44dd-b329-efc5e1c42c1a','6d1d6697-8aaa-4257-b26c-25f8b9173150','google:ChdDSUhNMG9nS0VJQ0FnSUNCLTQyd3p3RRAB','google','I have eaten lunch here for years but sadly to say I won''t be coming back. The salsa they are serving with there chips is nothing but tomato sauce. The quality of food has gone down. There are much better Mexican restaurants in Charlottesville better food for the same price.',2,'2023-01-05','2026-11-12T02:03:12.175Z');
