INSERT OR IGNORE INTO reviews VALUES('059b8517-f5bc-4439-8337-8e99ee6e4ba8','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:Ci9DQUlRQUNvZENodHljRjlvT21wQlJXaEdPVzQ1TmpSME1uTlhRVWR3VUU0MlpXYxAB','google','Good dumplings and soup but ordered takeout and they left half my dumplings out of the bag.',3,'2026-05-13','2026-11-12T02:04:59.005Z');
INSERT OR IGNORE INTO reviews VALUES('85494513-6a56-484c-8a32-45712eb161b7','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:Ci9DQUlRQUNvZENodHljRjlvT2xwUFdFbE5ObHA1WnpRMVRXWkdSbHBRTWkxcU5HYxAB','google','Sat outside and enjoyed a wonderful soup and snack. Great to try!',4,'2026-04-29','2026-11-12T02:04:59.005Z');
INSERT OR IGNORE INTO reviews VALUES('f9e04772-69a1-4d99-97fc-f89a7fa9e918','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:ChZDSUhNMG9nS0VJQ0FnSUNXNkpDc0NBEAE','google','Good food, very friendly staff, functioning WiFi, Clean and calm to sit down for a meal. The sauce on dumplings is very tasty and the portion/price is great!',5,'2022-02-16','2026-11-12T02:04:59.005Z');
INSERT OR IGNORE INTO reviews VALUES('b234f91c-6971-4efc-834d-dd1e757ddc41','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:ChdDSUhNMG9nS0VJQ0FnSURHMExYTjl3RRAB','google','Love their dumplings. Always great service and very kind. Highly recommend',5,'2021-11-15','2026-11-12T02:04:59.005Z');
