INSERT OR IGNORE INTO reviews VALUES('1d0f382a-76eb-43a7-9c2b-fbb1e19c18b9','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:ChZDSUhNMG9nS0VJQ0FnSUQzaW9iNlV3EAE','google','Love the wonton soup. The dumplings are good to.',5,'2024-11-14','2026-11-12T02:04:59.005Z');
INSERT OR IGNORE INTO reviews VALUES('c2fd379d-00d3-4ccc-abf0-96de17b88fd2','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:ChZDSUhNMG9nS0VJQ0FnSURuci0zWmZREAE','google','I really do love the food here but every single time I have been here, the lady at the front gives us attitude and despite asking for two orders, she puts our order in one plate and bin - making it super inconvenient to eat and also very weird for friends who are stopping by for lunch. When I asked for an extra fork (because she only gave us one to share), she said no.',2,'2024-10-11','2026-11-12T02:04:59.005Z');
INSERT OR IGNORE INTO reviews VALUES('9fa2cca0-8166-41c6-abc8-aeae7cd613c5','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:ChdDSUhNMG9nS0VJQ0FnSUNIX01IZWt3RRAB','google','Fried veggie dumplings and hot and sour soup are fantastic.  Also inexpensive, great place.',5,'2024-09-02','2026-11-12T02:04:59.005Z');
