INSERT OR IGNORE INTO reviews VALUES('eca00b24-0694-40cb-8378-5290738cb4b6','8db61b55-ebac-4928-aa3c-29234f315832','google:ChZDSUhNMG9nS0VJQ0FnSURyaElfbU5BEAE','google','Great and historic spot for a quick meal day or night. Never had a bad meal there. It’s the corner so parking isn’t easy, so plan ahead.',5,'2024-07-14','2026-11-12T02:10:36.430Z');
INSERT OR IGNORE INTO reviews VALUES('01f44183-1e39-45ab-a151-ceb0a4c6f99c','8db61b55-ebac-4928-aa3c-29234f315832','google:ChZDSUhNMG9nS0VJQ0FnSUNyNHZfN0ZREAE','google','First time here.  One of the smallest places I have been in.  Would go go back',4,'2024-07-05','2026-11-12T02:10:36.430Z');
INSERT OR IGNORE INTO reviews VALUES('435bf4fb-7f92-4e2d-80f6-673649b4917f','8db61b55-ebac-4928-aa3c-29234f315832','google:ChdDSUhNMG9nS0VJQ0FnSURMdWJyZzJBRRAB','google','Exactly what you hope to find close to a university campus. Great staff and service. A charming experience that feels like it’s been the same for decades or a century. Interesting drink menu. Good for families. The food was good too!',4,'2024-06-28','2026-11-12T02:10:36.430Z');
