INSERT OR IGNORE INTO reviews VALUES('5dca615f-6888-4153-9927-a642aeda42ad','8db61b55-ebac-4928-aa3c-29234f315832','google:ChZDSUhNMG9nS0VJQ0FnSUNMNDRQeVN3EAE','google','American fare, decent prices',3,'2024-06-22','2026-11-12T02:10:36.430Z');
INSERT OR IGNORE INTO reviews VALUES('8ed032a6-2ece-44c3-9226-7d670767f082','8db61b55-ebac-4928-aa3c-29234f315832','google:ChZDSUhNMG9nS0VJQ0FnSUNMMWN1U09BEAE','google','Great little place. Good food, good atmosphere.',4,'2024-06-22','2026-11-12T02:10:36.430Z');
INSERT OR IGNORE INTO reviews VALUES('5c2722bd-1a7c-4f45-9120-4c7b3b08cc30','8db61b55-ebac-4928-aa3c-29234f315832','google:ChdDSUhNMG9nS0VJQ0FnSUNMbFB2MzhBRRAB','google','My sister and I were in town for a one-night getaway!  We were ravenous after a long, enjoyable but tiring day and had been searching for over an hour for a good place for dinner when my sister, fortunately, finally grabbed the first street parking space she saw. We ended up right in front of The Virginian - lucky us!  We sat across from each other in a delightful wooden booth, tasted an excellent Classic Gimlet and then devoured our perfectly cooked half-pound burgers with everything-fresh salads.  All of this was enhanced by outstanding service (thank you, Terri!) and the warm, cozy atmosphere in such a historic place. We will be back!',5,'2024-06-15','2026-11-12T02:10:36.430Z');
INSERT OR IGNORE INTO reviews VALUES('cef16cec-0cf9-4788-8d65-f09e56213589','8db61b55-ebac-4928-aa3c-29234f315832','google:ChZDSUhNMG9nS0VJQ0FnSUR6MXF1MkNBEAE','google','Wow - great food at a reasonable price. The wait staff is very friendly.',5,'2024-06-09','2026-11-12T02:10:36.430Z');
