INSERT OR IGNORE INTO reviews VALUES('89378c98-dc82-4037-b468-f40af6561d33','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChZDSUhNMG9nS0VJQ0FnSUNSeDZqZUFnEAE','google','I have eaten here MANY times and while the pizza is ehhhh it is definitely better than most places on the corner. Avoid the calzones. Order some Johnny Knots. Don''t go here past 6pm if you want to avoid undergrads swamping the joint.',4,'2023-04-12','2026-11-12T02:15:25.781Z');
