INSERT OR IGNORE INTO reviews VALUES('301bdfce-0482-49f2-9293-5bd6934263a7','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChZDSUhNMG9nS0VJQ0FnSUNha0tLN2F3EAE','google','A bit pricey but really good overall I got the calzone and it was fantastic',5,'2021-07-21','2026-11-12T02:15:25.781Z');
