INSERT OR IGNORE INTO reviews VALUES('db82eb34-2a02-4529-b872-c4682ea35688','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChZDSUhNMG9nS0VJQ0FnSURNbjluME9BEAE','google','The Pizza is awesome!!!!',5,'2020-08-31','2026-11-12T02:15:25.781Z');
INSERT OR IGNORE INTO reviews VALUES('aeb4ce5f-708e-4629-a079-462df9b6880c','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChZDSUhNMG9nS0VJQ0FnSUM4X3RIRmJREAE','google','Pizza was phenomenal. Easily grabbed a top 5 slot for me on the first slice. Staff was very accommodating and the ordering process was super easy during these crazy times of covid',5,'2020-07-08','2026-11-12T02:15:25.781Z');
