INSERT OR IGNORE INTO reviews VALUES('a65e548b-5dac-4d83-9b0a-a0b9323480ac','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT2pkT1NUbHlVbkptUm05dGJWTkViM2RVTFVOaVgzYxAB','google','Leaving this review while eating their new wrap.. it’s so good, and the service was great !',5,'2026-01-22','2026-11-12T02:15:28.072Z');
INSERT OR IGNORE INTO reviews VALUES('343d6aa9-f6c7-4024-9351-47eb5739dd6d','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT21FMFgwWjBla1V4U0ZoZk0yWmFWbUpCY1cxRldrRRAB','google','Excellent food! It was fresh and flavorful. The multi colored plates added to the vibrancy of the place. Lots of interesting artwork on the walls, another feast for the eyes. A good variety of canned soda/juices as well; try the sour cherry juice. Overall, we were very happy with our choice.',5,'2026-01-18','2026-11-12T02:15:28.072Z');
INSERT OR IGNORE INTO reviews VALUES('ec9fee97-ac80-4eda-b333-c2f8fad30cfa','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT201R1QyZEhhVzU1VTJRNU9VbGhRVGxYUW1kM1JrRRAB','google','Great fresh food deserts and service .',5,'2026-01-18','2026-11-12T02:15:28.072Z');
