INSERT OR IGNORE INTO reviews VALUES('3c72e680-047e-41a1-9f1f-7b67e67f92eb','5e8a057b-5ad8-433d-96f3-6b5cceea1484','google:ChZDSUhNMG9nS0VJQ0FnSURKcXVHZE1REAE','google','We''ve been patronizing ''Rev Soup'' (as we refer to it) for many years (as of summer 2023), and it''s been pretty consistent in offering delicious, nutritious food at modest prices.',5,'2023-07-14','2026-11-12T02:15:29.082Z');
