INSERT OR IGNORE INTO reviews VALUES('bfa141c2-0efd-49ab-a107-41cf2070258b','eef4e05e-1a04-4212-a410-53c232168f7f','google:Ci9DQUlRQUNvZENodHljRjlvT2xGd1EyeEVRbUpKWkdneFVIVkdOMGR2WjNGUlVFRRAB','google','We received excellent service and hospitality on our first visit. Thank you for your food and the service! But the parking space was paid and limited, or maybe I didn’t know the area well😊. It looks like a family business, and I wish them continued success and better service.',5,'2026-07-28','2026-11-12T02:15:30.152Z');
