INSERT OR IGNORE INTO reviews VALUES('9d47428a-50ca-47c9-a8ef-4e0471248a9f','eef4e05e-1a04-4212-a410-53c232168f7f','google:Ci9DQUlRQUNvZENodHljRjlvT2paak1XRkhURmhJY1d3dGJtUmZjVlJUUjBwMlVYYxAB','google','Incredible food',5,'2026-05-13','2026-11-12T02:15:30.152Z');
