INSERT OR IGNORE INTO reviews VALUES('82347617-8956-487c-9fc5-2aba61f8dabc','ac247f38-5015-470b-a380-2fa7f4479d24','google:Ci9DQUlRQUNvZENodHljRjlvT25sUGIxQlFXSEl5TnpoMWIzaGpXSGhzU1hCRGQyYxAB','google','Incredible breakfast! One of my favourite breakfast dishes I’ve had, not huge portions but I prefer this ☺️',5,'2026-11-07','2026-11-12T15:33:54.953Z');
