INSERT OR IGNORE INTO reviews VALUES('52cd8282-3a86-487b-9314-700ead1d699c','ac247f38-5015-470b-a380-2fa7f4479d24','google:Ci9DQUlRQUNvZENodHljRjlvT21waGJrUXhVVVJsYW5OQ1FUSlNTMHBqVW14dldWRRAB','google','Avocado Toast is the best!!!',5,'2026-09-11','2026-11-12T15:33:54.953Z');
INSERT OR IGNORE INTO reviews VALUES('757ea9bc-b6b6-4aa6-8f6a-0d3c5d34b88a','ac247f38-5015-470b-a380-2fa7f4479d24','google:Ci9DQUlRQUNvZENodHljRjlvT2tFNFZWRTBXVXBzWW1kemFFa3labFpTWVVadlpXYxAB','google','Toby was great and we got to watch food coming out of the kitchen because of our seat location, and it was amazing to see how fast the food was served  all the food  looked so deliciou!  Kudos to the kitchen for working so hard and getting food to the customers and the presentation was great! I don’t like avocados and the avocado toast looked so good coming out to tables!  Wow great job to the staff!',5,'2026-09-06','2026-11-12T15:33:54.953Z');
