INSERT OR IGNORE INTO reviews VALUES('92354c24-d570-471f-90a6-2980817bd194','131fc3ae-d921-454b-9db7-674e50dc81b2','google:Ci9DQUlRQUNvZENodHljRjlvT2xoMGNIbHlVekEwZFhaT2VpMXpNbWR4VTBSdmMxRRAB','google','Low key place that was really good. Tuna tataki was on point and the sushi was really good. Small place, big taste.',5,'2025-08-21','2026-11-12T15:34:57.701Z');
