INSERT OR IGNORE INTO reviews VALUES('fb187f3b-76f4-4aee-bfea-cd9a2f9302ad','578fefe1-2f8e-4dc8-92f2-75516dc38fa8','google:Ci9DQUlRQUNvZENodHljRjlvT25SQ2VuSk9SRWRKV1dwdmJqTjJjVzEzZDFkYVUzYxAB','google','Quick service and friendly staff! I came in pretty close to closing time, but my food was still hot, correct, and delicious.',5,'2026-09-10','2026-11-12T15:35:31.597Z');
