INSERT OR IGNORE INTO reviews VALUES('90a0ff71-20a6-4dfd-a1da-549178570ff1','9fc07a7b-f4d8-4ba7-836b-40887ab1504d','google:Ci9DQUlRQUNvZENodHljRjlvT21aNlduSXpibWxqZDB0MlJ5MURVblZFVFZGclNHYxAB','google','This is the best Thai food in the area.  It is family owned and most of the ingredients they make even down to the spices!<br>The spring rolls were not greasy (flash fried) and Bennie the server was great!  She made great recommendations.  The portions are very generous!  Highly recommended!',5,'2026-10-15','2026-11-12T15:35:38.539Z');
