INSERT OR IGNORE INTO reviews VALUES('bddd7167-7ad4-4c04-b577-8f54fb2c10f9','8cf58b4a-3c65-48e7-b369-9a3679d84851','google:Ci9DQUlRQUNvZENodHljRjlvT214bldXeEdTME5TTmtaT1p6aGxlVlp6YW1sbllYYxAB','google','Delicious. I got the Baggby club sandwich combo. It was filling and fresh. As a surprise, they put a cookie in the bag!!! Going back again when I am in Charlottesville!!!',5,'2026-08-07','2026-11-12T15:35:46.982Z');
INSERT OR IGNORE INTO reviews VALUES('4a4e6fbe-1ac6-43fc-b027-e77d53fdfce6','8cf58b4a-3c65-48e7-b369-9a3679d84851','google:Ci9DQUlRQUNvZENodHljRjlvT25SaFluSTNWVGd3Wkc1Uk1rbGZiamxTYTB0RGVHYxAB','google','My favorite sandwich shop in town. The sundown is 11/10',5,'2026-07-16','2026-11-12T15:35:46.982Z');
