INSERT OR IGNORE INTO reviews VALUES('7f35ce7d-5170-4a6e-b519-2369ed3bc534','4ed3b601-3c96-49e9-b41f-fbb8f80e2066','google:Ci9DQUlRQUNvZENodHljRjlvT2pNMFpucDJUMTh4V25FMk9GZEJVbTFhYVV4SVJXYxAB','google','Everyone was very nice and the atmosphere was great.',4,'2026-09-26','2026-11-12T15:36:09.265Z');
INSERT OR IGNORE INTO reviews VALUES('eb6e0647-f2eb-47e9-87c7-4c0ac3967208','4ed3b601-3c96-49e9-b41f-fbb8f80e2066','google:Ci9DQUlRQUNvZENodHljRjlvT21WSFJYcFliVGQ1VDFFeFRtOW5lVVoyVVdReU4zYxAB','google','This place needs some work. Our server, Amanda, was single handedly running the restaurant. When she asked two other workers for some help they stared at her like a deer in headlights with no response. We were one of three in there, the food took entirely too long to come out.',3,'2026-09-23','2026-11-12T15:36:09.265Z');
