INSERT OR IGNORE INTO reviews VALUES('9dc2ff6b-16ae-4258-82f4-56561d535bbd','d5c64c04-d18e-41b9-9f5f-f2364676038d','google:Ci9DQUlRQUNvZENodHljRjlvT25OSVluQlRNR0ZqVWtJemNHWmtOMHBEWkdJNFEyYxAB','google','Didnt even get our food 2 hour wait',1,'2026-09-27','2026-11-12T15:36:18.140Z');
INSERT OR IGNORE INTO reviews VALUES('1a73e93c-b0ac-4971-918f-128e46cf545e','d5c64c04-d18e-41b9-9f5f-f2364676038d','google:Ci9DQUlRQUNvZENodHljRjlvT21NNVduSjZXRVl4WkdrelNuWlZWRkEyVkRZdE1XYxAB','google','Coty is an excellent server! His food recommendation, especially the wings, was excellent.',5,'2026-09-24','2026-11-12T15:36:18.140Z');
