INSERT OR IGNORE INTO reviews VALUES('69c438a7-ad0d-4d06-ba69-50425c0c2f33','d5c64c04-d18e-41b9-9f5f-f2364676038d','google:Ci9DQUlRQUNvZENodHljRjlvT25ocFRucEJSbmQ0WjJGa01teFJkVlZHUTFWUWJGRRAB','google','Food was good and the servers were very nice :)',5,'2026-09-22','2026-11-12T15:36:18.140Z');
INSERT OR IGNORE INTO reviews VALUES('d3c81a63-9447-499d-ae26-fc5f825fe82e','d5c64c04-d18e-41b9-9f5f-f2364676038d','google:Ci9DQUlRQUNvZENodHljRjlvT25SWllsVXpia05FYzAxRlR6UTFhekJOU21sTVMxRRAB','google','I love this place and the service is great.',5,'2026-09-22','2026-11-12T15:36:18.140Z');
INSERT OR IGNORE INTO reviews VALUES('d07992d3-8694-4505-9963-62b8b85939be','d5c64c04-d18e-41b9-9f5f-f2364676038d','google:Ci9DQUlRQUNvZENodHljRjlvT2tsZlJXUmtRM05oWTJ0U1NGZEJOazFtYm1aVldHYxAB','google','Ja-whan was so nice!! He wasn’t even our server, but was extremely attentive and sweet!',5,'2026-09-22','2026-11-12T15:36:18.140Z');
INSERT OR IGNORE INTO reviews VALUES('0c4f03f4-fca2-42ce-aad1-df8de9d02b37','d5c64c04-d18e-41b9-9f5f-f2364676038d','google:Ci9DQUlRQUNvZENodHljRjlvT25OS1dIQkxhelpoWTFGVWNsWkNTeTF1U0hsMVFWRRAB','google','Me and my wife eat at BJ''S a lot and we always sit at the bar and we just love love  TIFFANY she is Soo nice and helpful 🫶🏽❤️',5,'2026-09-22','2026-11-12T15:36:18.140Z');
INSERT OR IGNORE INTO reviews VALUES('2b16137b-109a-47f8-8557-6ff32a313041','d5c64c04-d18e-41b9-9f5f-f2364676038d','google:Ci9DQUlRQUNvZENodHljRjlvT25Gek4wTmlRMmQxVG5nMk5uZ3dOWE4yT1daTExVRRAB','google','They were out of their signature courses. Had to go with Korean burger which was average . Just average overall.',3,'2026-09-20','2026-11-12T15:36:18.140Z');
INSERT OR IGNORE INTO reviews VALUES('342e15d6-2a60-4d2c-965f-59a27cd6c5d4','d5c64c04-d18e-41b9-9f5f-f2364676038d','google:Ci9DQUlRQUNvZENodHljRjlvT21GUlNYZGtPV1Z4T0VoNVdFSkJMVlUyVFZBMk9XYxAB','google','Our go to family dinner spot. Great food, lots of options, and great service. Ask for Alea. They were out of a few things today but she was very quick to accommodate and offer alternatives.',5,'2026-09-16','2026-11-12T15:36:18.140Z');
INSERT OR IGNORE INTO reviews VALUES('79902ba1-52fd-42ca-8b52-55ec66568e76','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2xWVmJ6Um1hREZyYjA5c01sbEVjRTFEWjE5UFUzYxAB','google','Gail was a great waitress. Very attentive. Will definitely be coming back!',5,'2026-11-12','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('e70f505b-f223-487a-b46f-0b4d213d9db9','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2pkQmMyWlJNWE5UWm5vME9FZG5RbVJGWVZSSldIYxAB','google','My server Katherine was a delight and very helpful! She recommended the rack of lamb which was a phenomenal choice. Great food and even better service!',5,'2026-11-11','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('0f5dd1e6-4818-4cab-adf8-9004b3589db6','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT25KUmVHTkplV2RtTkhFeVRsWmZVbDkwYWpSbGRrRRAB','google','Great atmosphere especially after a long trip visiting Charlottesville. Our waitress Soniya was very attentive got everything for us in a timely manner, and the cornbread was delicious! 10/10 we will definitely come back on our next trip!',5,'2026-11-11','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('5fee71ef-593e-4263-82c9-ffbad0c40f2d','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2xkMWFVUjNXblZtVDBFeFNrdzNkbVpyY1RNMlNuYxAB','google','The lamb and meatloaf were absolutely delicious, almost as amazing as our server, Katherine! We’ve been here so many times, but today was our first time trying these dishes, and they definitely did not disappoint. Katherine made our experience even better with her wonderful service. We’ll definitely be returning!',5,'2026-11-11','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('ba39fb7d-05a7-4d11-b2ab-13d3d9044b0b','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2pnemVGRm1XRU01Y0RKUk9XSkNibkZHUjB4Q2RHYxAB','google','Visited this restaurant today and it was awesome. I highly recommend it.❤️❤️❤️',5,'2026-11-10','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('fd268951-84f5-4df8-a990-19f24a67a461','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2w5eGNrRlRVRzlIVUZaUlFWOUlSVGhYTVV0eFVVRRAB','google','Great food, fast service and the best staff around! 10/10',5,'2026-11-07','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('b5db607e-c388-49a1-909c-bf6c0771a7d1','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2pKMFUxbFVkRVpmVWw4M2RIb3hkME5oYkZNM1NuYxAB','google','Let me first start with how fantastic our server Angela was.  Service was impeccable. The food, however, was not.  The fried chicken was flavorless and dry as a card board. The gravy tasted like nothing and just made the entire thing soggy. The sweet potato mash was a sloppy mess. Collards were inedible.  The shrimp and grits were okay. The best thing they make is the cornbread. Highly disappointing.',2,'2026-11-03','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('edeae028-82b6-45db-aad0-10965fdc4ad6','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2tsR1RtczRYemczUVdSRVpXeEdMWGxzYWtOcVpVRRAB','google','Food is decent but prices are extreme and portion sizes are not equivalent. Service is bad, no customer service and seemed irritated about having to do their job.',2,'2026-10-27','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('bb8012fb-0262-4dda-8a79-4bfd9ebd539d','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2s1MGNUWnRNa05YU1ROamNYbFFURzlyWlZJeFFuYxAB','google','We arrived before our reservations and they accommodated. Our server was Emilyne. She was lovely. Food was delish! We found our C’ville brunch spot! Can’t wait to come back soon!',5,'2026-10-25','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('3c7d3f28-fd81-4c40-9c2c-94d8f8dd4719','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT21sc1lVVXlPR3N4ZWtRME1tMXdTM05hZVhCa01sRRAB','google','The servers mina and ellyce are amazing!!! Such good personalities the hosts brittany and hailie also are amazing! great staff keep up the good work',5,'2026-10-24','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('958d880e-db5c-4f73-bef0-3e9e1fef72e6','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2xCZmJFZHRVMnhqU2paVU5FUkdVMVpOY21aSlowRRAB','google','Visiting Charlottesville, VA to attend a wedding was also an opportunity for a dinner date with my husband the night before. When I searched for dining options, I knew I wanted to visit The Ridley.<br><br>The restaurant fully lived up to my expectations.<br>The decor was upscale yet welcoming to couples, friendly gatherings and family celebrations.<br><br>Our sever Katherin was friendly and helpful in answering our questions about the menu.<br><br>The shrimp tacos were delicious and a filling portion size. I also enjoyed the parmesan truffle fries. We both enjoyed the NY style cheesecake topped with berries and the warm banana bread pudding with ice cream.<br><br>I appreciated the significance of this restaurant being named after Dr. Walter Ridley and was glad to learn more about University of Virginia’s history.',5,'2026-10-17','2026-11-12T15:36:19.959Z');
INSERT OR IGNORE INTO reviews VALUES('5cdc130f-95f3-4689-a057-0f15e18472a2','d921a995-5849-4262-9526-c25bb27252b7','google:Ci9DQUlRQUNvZENodHljRjlvT2tSbFUyaG5aWGxvTkUweE5WcEZhazFPWjNSNVEwRRAB','google','First time to the Ridley and enjoyed it. Our server Katherin was FANTASTIC! She was Super friendly and very attentive. Thanks Katherin!',5,'2026-10-16','2026-11-12T15:36:19.959Z');
