INSERT OR IGNORE INTO reviews VALUES('a8ad66a9-b982-42b4-8129-89853bcc1e75','164d01e6-c6d8-4290-b4dc-8337aeabf286','google:Ci9DQUlRQUNvZENodHljRjlvT2tsa2VrMHRPVzh0YjNBNVRHbFFWazF1YkhCdE1GRRAB','google','I had the,"Philly" steak sandwich at my visit on Oct 30th. I have to say I was so disappointed. This ranks up in the 5 worst sandwiches I have eaten in many 67 yrs. It was way too salty and the meat was so chopped up in very small pieces which were over cooked. I enjoy this restaurant, but will never order that sandwich again 😡',2,'2026-10-31','2026-11-12T15:36:35.256Z');
INSERT OR IGNORE INTO reviews VALUES('c2cf02e2-3d33-4493-8557-3255cf071660','164d01e6-c6d8-4290-b4dc-8337aeabf286','google:Ci9DQUlRQUNvZENodHljRjlvT21wWkxWRk1WekpWVW1OR1VXOXhUMmw2Tm1GSk5YYxAB','google','This  was our first time at this restaurant and we live an hour away and we definitely would come back again . Food was excellent !',5,'2026-10-28','2026-11-12T15:36:35.256Z');
