INSERT OR IGNORE INTO reviews VALUES('1b2faf4c-cfb6-4106-9589-70b7de684798','1fe7aa63-d361-42d4-b4f5-2d20af19aacd','google:Ci9DQUlRQUNvZENodHljRjlvT205UlNXTjBZbXcxWjBGeGVXZDVUVzA0U21oa1UzYxAB','google','I got lunch there and was surprised by their coffee. They roast their coffee beans, which is also sold at the counter. Amazing. I bought the beans afterwards.',5,'2026-09-28','2026-11-12T15:36:49.498Z');
