INSERT OR IGNORE INTO reviews VALUES('3a09f797-fdb1-42d9-b87d-789d6c85d0bd','3c59354c-78be-4335-ac27-a27ff4cce713','google:Ci9DQUlRQUNvZENodHljRjlvT25WV1drbDBUbWhOVG1KVmNFd3lRbVZDWHpGTk1FRRAB','google','So good!  The best pizza in Charlottesville, in my opinion!',5,'2025-06-06','2026-11-12T15:37:09.035Z');
