INSERT OR IGNORE INTO reviews VALUES('49305d59-7a8c-4c45-a2bd-cc93519c8471','3551e409-a383-459b-aea6-1274454ab1c9','google:Ci9DQUlRQUNvZENodHljRjlvT2kxbFFXeFNjMnRIZFd4SlpqSmpjRFV5Um14SFYwRRAB','google','We enjoyed the delicious cali girl sandwich and the scrumptious potatoes!<br>Honduras coffe me excellent and  chocolate raspberry latte !',5,'2026-02-24','2026-11-12T15:37:16.366Z');
