INSERT OR IGNORE INTO reviews VALUES('5be026b7-ed5b-4302-898d-329d3f024952','ad8e6fe5-bde9-4a6b-b586-3147a994c6c0','google:Ci9DQUlRQUNvZENodHljRjlvT25OeGVUSkViblZDVURkM2FVRnlPRGhxVDBWTkxVRRAB','google','If you like Thai food, this place is a must-visit. Ordered the MaMa Drunken Noodles with chicken and the traditional-style green curry with tofu, and both were outstanding. Highly recommend stopping by-you won’t be disappointed.',5,'2026-06-30','2026-11-12T15:38:12.307Z');
