INSERT OR IGNORE INTO reviews VALUES('385961aa-74a7-4b24-b13b-13e2fbdb4c13','5ab62811-604f-4c80-ab82-b9f10307ea66','google:Ci9DQUlRQUNvZENodHljRjlvT2poSlUyd3phakJoUjJ0UFJrWTJaRFozWHpaeFduYxAB','google','Totally fine Chinese food. Kind of greasy. The dumplings were pretty good.',3,'2026-08-18','2026-11-12T16:01:06.158Z');
