INSERT OR IGNORE INTO reviews VALUES('18e8f515-9faf-4973-824d-38fe10145e79','772e303b-6822-486b-baae-fdbf7539e71d','google:Ci9DQUlRQUNvZENodHljRjlvT2pObmVGcFBTWFJVTmxSNU9FOWlTMDkwUzNsc2QyYxAB','google','Food was pretty good. Not the best study spot though.',5,'2026-10-19','2026-11-12T16:01:11.404Z');
INSERT OR IGNORE INTO reviews VALUES('f4084468-c382-4b20-9b27-24764dd87f44','772e303b-6822-486b-baae-fdbf7539e71d','google:ChdDSUhNMG9nS0VJQ0FnSUNPM043YTRRRRAB','google','Stopped in for dinner. Was seated in the bar area. There were several men seated at the bar watching a football game. One was very loud and vulgar dropping the f bomb constantly. Those of us seated in the area including a family with small children were all bothered by this individual''s behavior however no one did anything about it. The bartender ignored it and the manager was apparently hold up in the kitchen avoiding a confrontation. I guess his alcohol tab trumped our meal tabs. Good to know Texas Roadhouse''s priorities.',4,'2026-10-17','2026-11-12T16:01:11.404Z');
