INSERT OR IGNORE INTO reviews VALUES('d20c990e-26d1-4be1-add8-1166556a0374','772e303b-6822-486b-baae-fdbf7539e71d','google:Ci9DQUlRQUNvZENodHljRjlvT2xkTVYwSTJhVkZ2Y2pOSllVVjNjVW80YzNwbk1HYxAB','google','Had an excellent meal here. Our server was friendly and attentive. The food was excellent, especially the pork barbecue. And the peanuts are always a nice appetizer.',5,'2026-10-11','2026-11-12T16:01:11.404Z');
